        body,
        .support-card,
        input {
          color: CanvasText;
          background: Canvas;
        }

        .support-card,
        input {
          border-color: CanvasText;
        }

        .eyebrow,
        .intro,
        .helper-text,
        .status-message,
        footer,
        .required-marker,
        .optional-marker {
          color: CanvasText;
        }

        button,
        .skip-link {
          color: ButtonText;
          background: ButtonFace;
          border: 2px solid ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const fields = [
        {
          id: "full-name",
          label: "Full name",
          name: "fullName",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Morgan"
        },
        {
          id: "email-address",
          label: "Email address",
          name: "email",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@example.com"
        },
        {
          id: "phone-number",
          label: "Phone number",
          name: "phone",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "(555) 123-4567",
          helperText: "Expected format: (555) 123-4567 or +1 555 123 4567."
        }
      ];

      function createElement(tagName, attributes = {}, children = []) {
        const element = document.createElement(tagName);

        Object.entries(attributes).forEach(([name, value]) => {
          if (value === false || value === null || value === undefined) {
            return;
          }

          if (name === "className") {
            element.className = value;
            return;
          }

          if (name.startsWith("on") && typeof value === "function") {
            element.addEventListener(name.slice(2).toLowerCase(), value);
            return;
          }

          if (value === true) {
            element.setAttribute(name, "");
            return;
          }

          element.setAttribute(name, value);
        });

        children
          .flat()
          .filter((child) => child !== null && child !== undefined)
          .forEach((child) => {
            element.append(
              child instanceof Node ? child : document.createTextNode(child)
            );
          });

        return element;
      }

      function Header() {
        return createElement("header", {}, [
          createElement("p", { className: "eyebrow" }, ["Support center"]),
          createElement("h1", {}, ["How can we help?"]),
          createElement("p", { className: "intro" }, [
            "Send your contact details and our support team will follow up with the next available specialist."
          ])
        ]);
      }

      function FormField({ id, label, helperText, required, ...inputProps }) {
        const helperId = helperText ? `${id}-help` : null;

        return createElement("div", { className: "form-field" }, [
          createElement("label", { for: id }, [
            label,
            " ",
            createElement(
              "span",
              {
                className: required ? "required-marker" : "optional-marker"
              },
              [required ? "(required)" : "(optional)"]
            )
          ]),
          createElement("input", {
            id,
            required,
            "aria-required": required ? "true" : null,
            "aria-describedby": helperId,
            ...inputProps
          }),
          helperText
            ? createElement("p", { className: "helper-text", id: helperId }, [
                helperText
              ])
            : null
        ]);
      }

      function ContactForm() {
        const status = createElement(
          "p",
          {
            className: "status-message",
            id: "form-status",
            "aria-live": "polite"
          },
          []
        );

        const form = createElement(
          "form",
          {
            className: "form-grid",
            action: "#",
            method: "post",
            novalidate: true,
            onSubmit: (event) => {
              event.preventDefault();
              status.textContent = "";

              const controls = Array.from(
                form.querySelectorAll("input")
              );
              controls.forEach((control) => {
                control.setAttribute(
                  "aria-invalid",
                  control.checkValidity() ? "false" : "true"
                );
              });

              const firstInvalid = controls.find(
                (control) => !control.checkValidity()
              );

              if (firstInvalid) {
                firstInvalid.focus();
                form.reportValidity();
                return;
              }

              status.textContent =
                "Thanks - your support contact details are ready to send.";
              form.reset();
              controls.forEach((control) => {
                control.setAttribute("aria-invalid", "false");
              });
            }
          },
          [
            fields.map((field) => FormField(field)),
            createElement("div", { className: "form-actions" }, [
              createElement("button", { type: "submit" }, [
                "Contact support"
              ]),
              status
            ])
          ]
        );

        form.addEventListener("input", (event) => {
          if (event.target.matches("input")) {
            event.target.setAttribute(
              "aria-invalid",
              event.target.checkValidity() ? "false" : "true"
            );
          }
        });

        return form;
      }

      function SupportContactPage() {
        return createElement("div", { className: "page-shell" }, [
          Header(),
          createElement("main", { id: "main-content" }, [
            createElement("section", { className: "support-card" }, [
              ContactForm()
            ])
          ]),
          createElement("footer", {}, [
            "Support is available Monday through Friday."
          ])
        ]);
      }

      document.getElementById("app").append(SupportContactPage());
    </script>
  </body>
</html>
